  "loc.enterInternetConnectionsAddress": "Voer het adres van je internetverbinding in als server (bijv. je MyFRITZ!-adres) – meestal via een sms-opdracht volgens de handleiding van de tracker.",
  "loc.enterShopAddressesUnder": "Winkeladressen voer je in onder Lijsten → Boodschappenlijst bewerken – als een winkel meerdere keren voorkomt, ook meerdere filialen. Als iemand daar een tijdje blijft, wordt de geplande boodschappentrip afgevinkt.",
