  "loc.gpsTracker": "🛰️ GPS-tracker",
  "loc.guide1": "Installeer de app <b>“Traccar Client”</b> (App Store of Google Play, gratis).",
  "loc.guide2": "Voer in de app onder <b>Device ID</b> (apparaat-ID) in:",
  "loc.guide3": "Voer onder <b>Server URL</b> in:",
  "loc.guide4": "Nauwkeurigheid <b>Medium</b>, afstand <b>50 m</b>. De app verstuurt dan alleen iets als je beweegt – niets als je stilstaat. Heb je meer velden (interval, heartbeat), zet heartbeat dan uit of op 0.",
  "loc.guide5": "Locatietoegang toestaan: <b>Altijd</b> en <b>Precieze locatie</b> aan.",
  "loc.guide6": "Zet de schakelaar <b>Service / Tracking</b> aan en <b>laat hem altijd aan</b> – klaar. Vanaf nu bepaal je alles in pinn.: “Permanent verzenden” aan of uit, “Eenmalig verzenden” en SOS. Zolang “Permanent verzenden” uit staat, ziet niemand je locatie en slaat pinn. geen route op.",
  "loc.guideIntro": "Zonder andere app werkt “📍 Locatie delen” direct in pinn. – maar alleen zolang pinn. open is. Zodat de locatie ook aankomt als pinn. gesloten is en het scherm vergrendeld, stuurt de gratis app “Traccar Client” die rechtstreeks naar pinn. (een Traccar-server is niet nodig). Hetzelfde voor iPhone en Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Deze poort moet in de FRITZ!Box naar de NAS worden doorgestuurd, omdat de tracker via het mobiele netwerk verbinding maakt.",
