  "loc.setup": "Instellen · {famDeviceName}",
  "loc.setupIntro": "Telefoons hebben verder niets nodig: iedereen kan direct in pinn. delen onder “Mijn locatie”. Op de achtergrond (pinn. gesloten) verstuurt de telefoon met de gratis app “Traccar Client” (iPhone en Android) – rechtstreeks naar pinn., een Traccar-server is niet nodig. Alleen GPS-trackers met een simkaart (bijv. aan een halsband) hebben de container “traccar” nodig. De locaties blijven op je NAS.",
