  "settings.calendar.info": "Elk profiel meldt zich aan met een eigen iCloud- of Google-account en vinkt daarvan de agenda’s aan: “Voor mij” is alleen zichtbaar voor je eigen profiel, “Gezin” wordt door iedereen in je gezin gezien en gebruikt. De anderen zien alleen van welk account een gezinsagenda komt – onherkenbaar gemaakt, bijv. m**l@g***l.com. Afspraken kunnen zoals gewoonlijk worden gemaakt, bewerkt, verplaatst en offline in de wachtrij gezet, en gaan rechtstreeks naar iCloud of Google (en dus naar de telefoon). Synchronisatie elke 15 minuten of met “Nu bijwerken”. Zonder account werkt ook een agenda die alleen op je pinn.-server staat. Herinneringen en dagoverzicht per push: privé-afspraken alleen naar jou.",
