  "smart.guide1": "1. Nieuwe opdracht “pinn Automatik”:",
  "smart.guide10": "Het apparaat moet hiervoor pinn. kunnen bereiken (wifi thuis of vpn). Elke actie wordt per taak maar één keer uitgevoerd; wat al met een knop is gestart, wordt niet opnieuw door de automatisering gestart.",
