  "smart.guide7": "– “Voer opdracht uit” – kies de waarde “kurzbefehl” als opdracht en de waarde “eingabe” als invoer",
  "smart.guide8": "2. Tabblad “Automatisering” → “Tijdstip” – één automatisering per tijdstip bovenaan, “Direct uitvoeren” → “pinn Automatik”.",
