  "smart.haDevices": "Apparaten via Home Assistant: {list}",
  "smart.haIntro": "De pinn.-server bestuurt Home Assistant rechtstreeks – knoppen werken op elk apparaat (ook Android), automatisering en “Bij afvinken” draaien zonder opdrachten. Met een statusentiteit wacht pinn. tot bijv. de robotstofzuiger echt klaar is.",
