  "smart.haOff": "Home Assistant niet gekoppeld",
  "smart.haOn": "Home Assistant gekoppeld",
  "smart.haSearching": "Zoeken naar Home Assistant …",
  "smart.haTip1": "Roborock: maak het apparaat “Robotstofzuiger” aan, kies hierboven de robot (vacuum.…) – pinn. laadt de kamers uit de kaart. Per actie “Kamerreiniging” met kamers en modus (stofzuigen, stofzuigen & dweilen, dweilen). “Kamer van de taak” gebruikt de kamer van de schoonmaaktaak in het huishouden – de namen moeten gelijk zijn aan die in de Roborock-app.",
  "smart.haTip2": "De robot dient ook als status: de volgende actie start pas als hij weer in het dock staat.",
  "smart.haTip3": "Scripts ontvangen de kamernaam als variabele <span class=\"font-mono\">raum</span> – zo kan één script alle kamers afhandelen.",
  "smart.haTip4": "Lampen/led’s: stel kleur en helderheid direct in bij de actie.",
  "smart.haTip5": "De automatisering draait elke minuut op de server – op de telefoon is geen automatisering nodig.",
  "smart.haToken": "Langlevende toegangstoken",
  "smart.haTokenHint": "In Home Assistant: linksonder op je profiel → tabblad “Beveiliging” → “Langlevende toegangstokens” → “Token aanmaken” en plak de lange tekenreeks volledig. Je hoeft er geen “Bearer” voor te zetten – pinn. voegt dat zelf toe (het geeft ook niets als het er wel staat). De token blijft op de server en wordt nooit naar apparaten gestuurd.",
