  "voice.widgetIntro": "Toont afspraken, taken en het boodschappenlijstje op het beginscherm en op het horloge – alleen lezen. Hiervoor geldt dezelfde geheime link als hierboven.",
  "voice.widgetIos1": "Installeer de gratis app <b>Scriptable</b> uit de App Store, open hem en tik rechtsboven op <b>+</b>.",
  "voice.widgetIos2": "Tik hier in pinn. op “Widgetscript kopiëren”, plak de tekst in Scriptable en noem het script <b>pinn</b>.",
  "voice.widgetIos3": "Houd het beginscherm ingedrukt → <b>+</b> → <b>Scriptable</b> → kies een formaat → tik op de widget → kies bij “Script” <b>pinn</b>. iOS ververst hem ongeveer elke 15 minuten.",
  "voice.widgetIosTitle": "iPhone-widget met Scriptable",
  "voice.widgetNeedOne": "Vink minstens één punt aan.",
  "voice.widgetNote": "Net als bij Siri moet de iPhone pinn. kunnen bereiken (wifi thuis of VPN). De link werkt als een wachtwoord – deel hem niet.",
  "voice.widgetPick": "Wat moet de widget tonen? Vink aan en kopieer het script – één script per widget.",
  "voice.widgetQuickCopy": "🔗 Snelkoppelingsscript kopiëren",
  "voice.widgetQuickHint": "Snelle toegang: een widget met drie knoppen – lijsten, financiën (met het valutateken van je regio) en taken. Een tik opent die pagina van pinn. in Safari, niet in de geïnstalleerde app; meld je daar één keer aan.",
  "voice.widgetScriptCopied": "Script gekopieerd.",
  "voice.widgetTasks": "Taken (zonder huishouden)",
  "voice.widgetTick": "In de middelgrote en grote widget tik je op een taak om die af te vinken – hij is dan ook in pinn. afgevinkt. iOS opent hiervoor even Scriptable.",
  "voice.widgetTitle": "📲 Widgets en ⌚ Apple Watch",
  "voice.widgetViews": "Andere weergave: vervang in de link <code>ansicht=heute</code> door <code>morgen</code>, <code>einkauf</code> of <code>alles</code>.",
  "voice.widgetWatch1": "Maak in de app <b>Opdrachten</b> op de iPhone een nieuwe opdracht en voeg de actie <b>“Haal inhoud van URL op”</b> toe.",
  "voice.widgetWatch2": "Tik hier op “Link voor de opdracht kopiëren” en plak hem als URL (methode GET).",
  "voice.widgetWatch3": "Voeg de actie <b>“Toon resultaat”</b> (of “Spreek tekst uit”) toe met “Inhoud van URL”.",
  "voice.widgetWatch4": "Tik op <b>ⓘ</b>, zet <b>Toon op Apple Watch</b> aan en geef de opdracht een naam, bijv. <b>pinn vandaag</b>. Start hem op het horloge in de app Opdrachten of zeg “Hé Siri, pinn vandaag”.",
  "voice.widgetWatchTitle": "Apple Watch met een opdracht",
